package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.*;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.golems.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class ScoutProbe {
 static final BlockPos Q=new BlockPos(680,205,8);static final UUID OWNER=UUID.fromString("2b85ce37-c238-47f9-9a04-329d58ce0491");static ServerPlayer p;static int ticks;static boolean done;
 static final GolemDesign SMART=new GolemDesign(3,4,0,3,2),OLD=new GolemDesign(3,2,0,3,1);
 static GolemBuilder press(BlockPos q){p.level().removeBlock(q,false);p.level().setBlockAndUpdate(q,GolemContent.BUILDER.get().defaultBlockState());p.setPos(Vec3.atCenterOf(q).add(0,1,0));return (GolemBuilder)p.level().getBlockEntity(q);}
 static void complete(GolemBuilder b){while(b.working())check(b.insert("machina",Direction.DOWN,false),"Cannot finish paid scout job");check(!b.insert("machina",Direction.DOWN,false),"Finished scout job consumed extra Machina");}
 static WorkerGolem worker(GolemDesign d){var g=new WorkerGolem(GolemContent.GOLEM.get(),p.level());g.configure(p,d,Q,6);return g;}
 static void bounds(){var l=p.level();var ordinary=worker(new GolemDesign(3,1,0,3));var scout=worker(SMART);check(ordinary.workRadius()==32&&scout.workRadius()==48,"Head radius incorrect");for(int offset:new int[]{32,33,40,48,49}){var s=GolemProbe.seal(p,SealKind.PROVIDER,Q.east(offset));s.channel=6;s.serverTick();boolean in=offset<=48;check(GolemLogistics.belongs(s,scout)==in&&s.claim(scout)==in,"Scout lease/delivery boundary wrong at "+offset);s.release(scout);check(GolemLogistics.belongs(s,ordinary)==(offset<=32),"Old head radius expanded at "+offset);check(SealEntity.nearby(l,scout).contains(s)==in,"Scout index boundary wrong at "+offset);GolemClient.remove(s);}var s=GolemProbe.seal(p,SealKind.FILL,Q.east(40));s.channel=5;check(!s.claim(scout)&&!GolemLogistics.belongs(s,scout),"Scout bypassed channel");s.channel=6;scout.setHome(Q.west(20));check(!s.claim(scout)&&!GolemLogistics.belongs(s,scout),"Changed home retained out-of-range lease");GolemClient.remove(s);Thaumcraft.LOGGER.info("SCOUT_BOUNDS_OK: 32/33/40/48/49, index, lease, saved delivery eligibility, channel and home changes");}
 static void write(){bounds();var b=press(Q);var menu=new GolemBuilderMenu(123,p.getInventory(),b);for(int n=0;n<4;n++)check(menu.clickMenuButton(p,1),"Head menu cycle rejected");check(menu.design().head()==4,"Menu did not sync Smart Scout");b.draft=new GolemDesign(3,3,0,0);GolemProbe.giveComponents(p,b.draft);var state=thaumcraft.research.ResearchService.state(p);thaumcraft.research.KnowledgeStore.write(p,state.stage("MINDBIOTHAUMIC",0));check(b.start(p),"Clockwork Scout incorrectly needs biothaumic research");complete(b);check(b.output.getItem(0).get(GolemContent.DESIGN.get()).head()==3,"Scout press output lost head");b.output.clearContent();thaumcraft.research.KnowledgeStore.write(p,state);b.draft=SMART;GolemProbe.giveComponents(p,SMART);var before=java.util.stream.IntStream.range(0,36).mapToObj(i->p.getInventory().getItem(i).copy()).toList();thaumcraft.research.KnowledgeStore.write(p,state.stage("GOLEMVISION",0));check(!b.start(p)&&java.util.stream.IntStream.range(0,36).allMatch(i->ItemStack.matches(before.get(i),p.getInventory().getItem(i))),"Missing vision research charged components");thaumcraft.research.KnowledgeStore.write(p,state);check(b.start(p)&&p.getInventory().isEmpty()&&b.insert("machina",Direction.DOWN,false)&&!b.edit(p,1)&&!b.edit(p,5)&&!b.start(p),"Scout payment/lock failed");var old=press(Q.west(4));old.draft=OLD;GolemProbe.giveComponents(p,OLD);check(old.start(p)&&old.insert("machina",Direction.DOWN,false),"Old head payment changed");var g=worker(SMART);g.setMode(2);g.setCustomName(Component.literal("Persistent smart scout"));g.cargo.setItem(0,new ItemStack(Items.EMERALD,21));g.setHealth(5);check(l().addFreshEntity(g),"Cannot persist scout");Thaumcraft.LOGGER.info("SCOUT_WRITE_OK: menu, clockwork/biothaumic distinction, atomic research/payment, paid old/new jobs and saved scout cargo");}
 static ServerLevel l(){return p.level();}
 @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("scout-write")&&!mode.equals("scout-read"))return;var l=e.getServer().overworld();for(int x=41;x<=45;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);l.setChunkForced(12,0,true);l.setChunkForced(32,0,true);l.setChunkForced(33,0,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"ScoutProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean o){}@Override public void sendOverlayMessage(Component c){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};knowledge(p);}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("scout-write")&&!mode.equals("scout-read")||done||++ticks<60)return;var l=p.level();if(mode.equals("scout-write")){for(var g:l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(12)))g.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-2),Q.offset(52,-1,2)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());write();}else{var b=(GolemBuilder)l.getBlockEntity(Q);check(b.working()&&b.draft.equals(SMART)&&b.remaining()==SMART.cost()-1,"Paid Smart Scout job lost progress");complete(b);check(b.output.getItem(0).get(GolemContent.DESIGN.get()).equals(SMART),"Resumed Smart Scout output changed");var old=(GolemBuilder)l.getBlockEntity(Q.west(4));check(old.working()&&old.draft.equals(OLD)&&old.remaining()==OLD.cost()-1,"Paid old head job changed");complete(old);check(old.output.getItem(0).get(GolemContent.DESIGN.get()).equals(OLD),"Old head output changed");check(l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(12)).stream().anyMatch(g->g.design().equals(SMART)&&g.head()==4&&g.workRadius()==48&&g.cargo.getItem(0).getCount()==21&&g.getHealth()==5&&g.getNavigation() instanceof GolemNavigation.Climber),"Saved Scout lost head/radius/cargo/health/navigation");bounds();Thaumcraft.LOGGER.info("SCOUT_RESTART_OK: old/new paid jobs and Smart Scout design, navigation, cargo, health and radius");}
 check(l.getEntitiesOfClass(WorkerGolem.class,new AABB(MobilityProbe.Q).inflate(20)).stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent flyer")&&g.head()==1&&g.design().equals(MobilityProbe.FLYER)&&g.workRadius()==32&&g.cargo.getItem(0).getCount()==19&&g.getHealth()==5),"Actual port.23 flyer changed");check(l.getEntitiesOfClass(WorkerGolem.class,new AABB(GolemProbe.Q).inflate(16)).stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent porter")&&g.head()==1&&g.workRadius()==32&&g.cargo.getItem(0).getCount()==17&&g.getHealth()==7),"Actual old porter changed");Thaumcraft.LOGGER.info("SCOUT_PORT23_OK: existing flyer and old porter retained heads, radii, cargo and health");done=true;e.server().halt(false);}
}
